\title[The trace-set filter is exact, half-sized, and non-amplifying]
{The Trace-Set Filter is Exact, Exactly Half-Sized, and Non-Amplifying}

\subjclass[2020]{11Y05, 11A51, 11T24, 68Q17}
\keywords{trace set, semiprime factorization, Fermat's method, Legendre symbol,
quadratic residues, Chinese remainder theorem, sieve barrier, primorial, interval hint}

